 raise TypeError("text must be a string")
 if not text:
 raise ValueError("empty string")
 unit_order = {'d': 0, 'h': 1, 'm': 2, 's': 3}
 unit_seconds = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
 last_unit = -1
 total = 0
 i = 0
 n = len(text)
 while i < n:
 # parse integer
 j = i
 while j < n and text[j].isdigit():
 j += 1
 if j == i:
