import datetime

def add_months(date_str, n):
 # Validate n
 if not isinstance(n, int) or type(n) is bool:
 raise TypeError("n must be an int (bool is not considered an int)")

 # Parse the date string
 try:
 date = datetime.datetime.strptime(date_str, "%Y-%m-%d")
 except ValueError:
 raise ValueError("Invalid date string format")

 # Validate year range
 if not (1 <= date.year <= 9999):
 raise ValueError("Year must be between 1 and 9999")

 # Add months
 year = date.year
 month = date.month + n
 while month > 12:
 month -= 12
 year += 1
 while month < 1:
 month += 12
 year -= 1

 # Clamp day to last day of target month
 day = date.day
 while day > datetime.date(year, month, 1).days:
 day -= 1

 # Validate year range after adjustment
 if not (1 <= year <= 9999):
 raise ValueError("Resulting year is outside 1..9999")

 # Return ISO date string
 return date.strftime("%Y-%m-%d")
